const DAYS = ['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];
const MEALS = ['Pequeno-almoço','Almoço','Jantar'];


const G='#00683F', D='#153B2B', O='#FF7900', MUTED='#748079', PALE='#F4F8F5', LINE='#E8EEE9', RED='#D64748';
const photos=[require('./assets/food1.jpg'),require('./assets/food2.jpg'),require('./assets/food3.jpg'),require('./assets/food4.jpg'),require('./assets/food5.jpg'),require('./assets/food6.jpg'),require('./assets/food6.jpg')];
const recipeImage = r => r.imageUrl&&/^https:\/\//.test(r.imageUrl)?{uri:r.imageUrl}:photos[Math.max(0,Number(r.img)||0)%photos.length];
const LOGO=require('./assets/logo-mark.png');
const money = v => v == null ? 'Preço indisponível' : `CHF ${Number(v).toFixed(2)}`;
const norm = s => String(s||'').trim().toLocaleLowerCase('pt');
const short = s => String(s||'').slice(0,140);
const initial={pantry:[],shopping:[],equipment:['fogao','forno'],servings:2,plan:{},favorites:[],expenses:[],receipt:null};
const defaultProduct = name => DEFAULT_PRODUCTS.find(x=>norm(x.name)===norm(name))||{name,unit:'un',category:'Outros',emoji:'🛒',min:1};
const findStock = (pantry,name) => pantry.find(p=>norm(p.name)===norm(name));
const scaledIngredients=(recipe,servings)=>recipe.ingredients.map(x=>({...x,qty:x.unit==='un'?Math.ceil(x.qty*servings/recipe.servings):Math.round(x.qty*servings/recipe.servings*10)/10}));
const shortage = (recipe,pantry,servings=recipe.servings) => scaledIngredients(recipe,servings).filter(x=>stockAmount(pantry,x)<Number(x.qty));
const niceName = s => String(s||'').trim();
const numberOf=x=>Number(String(x).trim().replace(',','.'));
const convertUnits=(amount,from,to)=>{const q=numberOf(amount);if(!Number.isFinite(q))return null;if(from===to)return q;const pairs={'kg:g':1000,'g:kg':.001,'L:ml':1000,'ml:L':.001};return pairs[`${from}:${to}`]!==undefined?q*pairs[`${from}:${to}`]:null};
const stockAmount=(pantry,ingredient)=>{const p=findStock(pantry,ingredient.name);return p?convertUnits(p.qty,p.unit,ingredient.unit)??0:0};
const useFetch = (path,enabled=true) => {
  const [state,set] = useState({items:[],status:'offline'});
  useEffect(()=>{if (!enabled || !API_URL){set({items:[],status:'offline'});return;}let dead=false;
    (async()=>{try{let ctrl=new AbortController();let timer=setTimeout(()=>ctrl.abort(),9000);let r=await fetch(`${API_URL}${path}`,{signal:ctrl.signal});clearTimeout(timer);if(!r.ok)throw Error(`HTTP ${r.status}`);const j=await r.json();if(!dead)set({items:Array.isArray(j)?j:(j.items||[]),status:'online'});}catch(e){if(!dead)set({items:[],status:'error'})}})();
    return()=>{dead=true};
  },[path,enabled]);return state;
};

function Icon({name,size=20,color=G}){return <Ionicons name={name} size={size} color={color}/>}
function Brand({small=false}){return <View style={{flexDirection:'row',alignItems:'center'}}><Image source={LOGO} style={{width:small?30:36,height:small?30:36,resizeMode:'contain',marginRight:5}}/><Text style={{fontSize:small?20:24,fontWeight:'900',letterSpacing:-1,color:G}}>Meal<Text style={{color:O}}>Swiss</Text></Text></View>}
function H({title,subtitle,action,onPress}){return <View style={s.sectionHead}><View style={{flex:1}}><Text style={s.sectionTitle}>{title}</Text>{subtitle?<Text style={s.note}>{subtitle}</Text>:null}</View>{action?<TouchableOpacity onPress={onPress}><Text style={s.link}>{action}</Text></TouchableOpacity>:null}</View>}
function Pill({text,onPress,active=false,tone='green'}){return <TouchableOpacity onPress={onPress} style={[s.pill,active&&{backgroundColor:tone==='orange'?O:G,borderColor:tone==='orange'?O:G}]}><Text style={{fontSize:11,fontWeight:'800',color:active?'#FFF':D}}>{text}</Text></TouchableOpacity>}
function CTA({text,onPress,outline=false,color=G,disabled=false,icon=null}){return <TouchableOpacity disabled={disabled} onPress={onPress} style={[s.btn,{backgroundColor:outline?'#FFF':color,borderColor:color,opacity:disabled?.5:1}]}>{icon?<Icon name={icon} color={outline?color:'#FFF'} size={18}/>:null}<Text style={{color:outline?color:'#FFF',fontSize:13,fontWeight:'900',textAlign:'center'}}>{text}</Text></TouchableOpacity>}
function Notice({text,kind='neutral'}){return <View style={[s.notice,{backgroundColor:kind==='warn'?'#FFF4E9':'#F0F8F2'}]}><Icon name={kind==='warn'?'information-circle-outline':'shield-checkmark-outline'} color={kind==='warn'?'#BC650B':G} size={18}/><Text style={{color:kind==='warn'?'#82500B':G,flex:1,fontSize:12,lineHeight:18}}>{text}</Text></View>}
function ProductRow({p,qty,unit,onMinus,onPlus}){const low=qty===0?'Esgotado':qty<=p.min?'Stock baixo':'Em stock';const red=qty===0,orange=qty>0&&qty<=p.min;return <View style={s.productRow}><View style={{width:39,height:41,borderRadius:10,backgroundColor:'#F8FAF8',alignItems:'center',justifyContent:'center'}}><Text style={{fontSize:26}}>{p.emoji||'🛍️'}</Text></View><View style={{flex:1}}><Text style={s.productName}>{p.name}</Text><Text style={s.note}>{qty} {unit}</Text></View><View style={[s.stockBadge,{backgroundColor:red?'#FCE8E8':orange?'#FFF3DF':'#E3F6EC'}]}><Text style={{fontSize:9,fontWeight:'900',color:red?RED:orange?'#B46A0B':G}}>{low}</Text></View><TouchableOpacity accessibilityLabel={`Diminuir quantidade de ${p.name}`} style={s.qtyBtn} onPress={onMinus}><Icon name="remove" color={G} size={16}/></TouchableOpacity><Text style={{fontSize:12,color:D,fontWeight:'900',minWidth:22,textAlign:'center'}}>{qty}</Text><TouchableOpacity accessibilityLabel={`Aumentar quantidade de ${p.name}`} style={s.qtyBtn} onPress={onPlus}><Icon name="add" color={G} size={16}/></TouchableOpacity></View>}
function HomeRecipeCard({r,onPress,isFavorite=false,onFavorite}){return <TouchableOpacity onPress={onPress} style={s.homeRecipeCard} activeOpacity={.84}><View><Image source={recipeImage(r)} style={s.homeRecipePhoto}/><TouchableOpacity onPress={onFavorite} style={s.homeHeart}><Icon name={isFavorite?'heart':'heart-outline'} size={16} color={isFavorite?O:'#FFFFFF'}/></TouchableOpacity></View><Text numberOfLines={2} style={s.homeRecipeName}>{r.name}</Text><Text style={s.homeRecipeInfo}>{r.minutes} min · {r.servings} pessoas</Text></TouchableOpacity>}
function FoodCard({r,onPress,isFavorite=false,onFavorite}){return <TouchableOpacity style={s.foodCard} onPress={onPress} activeOpacity={.86}><View><Image source={recipeImage(r)} style={s.foodImage}/><TouchableOpacity style={s.heart} onPress={onFavorite}><Icon name={isFavorite?'heart':'heart-outline'} color={isFavorite?O:D} size={19}/></TouchableOpacity></View><View style={{padding:9}}><Text numberOfLines={2} style={s.foodTitle}>{r.name}</Text><Text style={s.note}><Icon name="time-outline" color={MUTED} size={11}/> {r.minutes} min  ·  {r.servings} pessoas</Text><View style={{marginTop:7,flexDirection:'row',alignItems:'center'}}><Text style={{color:G,fontSize:10,fontWeight:'800'}}>Ver receita</Text><Icon name="chevron-forward" color={G} size={11}/></View></View></TouchableOpacity>}

function MealSwiss(){
  const insets=useSafeAreaInsets();
  const [data,setData]=useState(initial),[loaded,setLoaded]=useState(false),[started,setStarted]=useState(false),[tab,setTab]=useState('Início'),[detail,setDetail]=useState(null),[search,setSearch]=useState(''),[filter,setFilter]=useState('Todas'),[pantryFilter,setPantryFilter]=useState('Todos'),[modal,setModal]=useState(''),[inputName,setInputName]=useState(''),[inputQty,setInputQty]=useState('1'),[inputUnit,setInputUnit]=useState('un'),[inputCategory,setInputCategory]=useState('Outros'),[selectedDay,setSelectedDay]=useState(DAYS[0]),[selectedMeal,setSelectedMeal]=useState(MEALS[1]),[aiLoading,setAiLoading]=useState(false),[aiResults,setAiResults]=useState([]),[priceQuery,setPriceQuery]=useState(''),[store,setStore]=useState('Todos'),[receiptPreview,setReceiptPreview]=useState(null),[expensePeriod,setExpensePeriod]=useState('Mês');
  const feed=useFetch('/api/prices');const liveRecipes=useFetch('/api/recipes');const cooks=useFetch('/api/cooks');const offers=useFetch('/api/offers');const promotions=useFetch('/api/promotions');const [paymentsReady,setPaymentsReady]=useState(false);const [payBusy,setPayBusy]=useState(false);
  useEffect(()=>{if(!API_URL)return;fetch(`${API_URL}/health`).then(r=>r.json()).then(v=>setPaymentsReady(v.twint===true)).catch(()=>setPaymentsReady(false))},[]);
  useEffect(()=>{(async()=>{try{const raw=await AsyncStorage.getItem('mealswiss.local.v2');if(raw){const prev=JSON.parse(raw);setData({...initial,...prev});if(prev.receipt)setReceiptPreview(prev.receipt);}}catch{}try{const w=await AsyncStorage.getItem('mealswiss.welcome.v2');setStarted(w==='yes')}catch{}setLoaded(true)})()},[]);
  useEffect(()=>{if(loaded)AsyncStorage.setItem('mealswiss.local.v2',JSON.stringify(data)).catch(()=>{})},[data,loaded]);
  const patch=(key,fn)=>setData(d=>({...d,[key]:typeof fn==='function'?fn(d[key]):fn}));
  const go=t=>{setTab(t);setDetail(null);setSearch('');setFilter('Todas')};
  const catalogue=useMemo(()=>[...RECIPES,...liveRecipes.items.filter(r=>r.published===true&&Array.isArray(r.ingredients)&&Array.isArray(r.steps)).map(r=>({...r,servings:Number(r.servings)||2,minutes:Number(r.minutes)||25,equipment:Array.isArray(r.equipment)?r.equipment:[],img:6}))],[liveRecipes.items]);
  const recipes=useMemo(()=>catalogue.filter(r=>r.equipment.every(e=>data.equipment.includes(e))),[catalogue,data.equipment]);
  const recommendations=useMemo(()=>recipes.map(r=>({...r,missing:shortage(r,data.pantry,data.servings).length})).sort((a,b)=>a.missing-b.missing||a.minutes-b.minutes),[recipes,data.pantry]);
  const favorite = id => patch('favorites',a=>a.includes(id)?a.filter(x=>x!==id):[...a,id]);
  const viewRecipe=r=>{setTab('Receitas');setDetail(r)};
  const addShopping = (ingredients)=>patch('shopping',old=>{
    let next=[...old];ingredients.forEach(x=>{const idx=next.findIndex(y=>norm(y.name)===norm(x.name));if(idx<0)next.push({id:`${Date.now()}-${next.length}`,name:x.name,qty:x.qty||1,unit:x.unit||'un',done:false,store:'Todos'});else {let converted=convertUnits(x.qty||1,x.unit||'un',next[idx].unit);if(converted===null)next.push({id:`${Date.now()}-${next.length}`,name:x.name,qty:x.qty||1,unit:x.unit||'un',done:false,store:'Todos'});else next[idx]={...next[idx],qty:Number(next[idx].qty||0)+converted}};});return next;
  });
  const adjustPantry = (name,delta)=>patch('pantry',old=>old.map(p=>norm(p.name)!==norm(name)?p:{...p,qty:Math.max(0,Number(p.qty)+delta)}));
  const savePantry=()=>{let n=niceName(inputName),v=numberOf(inputQty);if(!n||!(v>0))return Alert.alert('Confirma os dados','Indica um produto e uma quantidade positiva.');let base=defaultProduct(n),match=data.pantry.find(p=>norm(p.name)===norm(n));let converted=match?convertUnits(v,inputUnit,match.unit):v;if(converted===null)return Alert.alert('Unidades incompatíveis',`Este produto está registado em ${match.unit}. Escolhe uma unidade compatível.`);patch('pantry',a=>match?a.map(p=>norm(p.name)===norm(n)?{...p,qty:Number(p.qty)+converted}:p):[...a,{...base,name:n,unit:inputUnit,qty:v,category:inputCategory,min:base.min||1}]);setModal('')};
  const saveShopping=()=>{let n=niceName(inputName);if(!n||!(numberOf(inputQty)>0))return Alert.alert('Indica um produto e uma quantidade');addShopping([{name:n,qty:numberOf(inputQty),unit:inputUnit}]);setModal('')};
  const prepareModal=(type,name='',qty='1',unit='un')=>{setInputName(name);setInputQty(qty);setInputUnit(unit);setInputCategory(defaultProduct(name).category);setModal(type)};
  const confirmCook=r=>{let miss=shortage(r,data.pantry,data.servings);if(miss.length)return Alert.alert('Ingredientes em falta',`Faltam: ${miss.map(x=>x.name).join(', ')}.`,[{text:'Voltar'},{text:'Adicionar às compras',onPress:()=>{addShopping(miss.map(i=>({...i,qty:Math.max(1,i.qty-Number(findStock(data.pantry,i.name)?.qty||0))})));go('Compras')}}]);Alert.alert('Já cozinhaste?', 'Só depois de confirmares serão descontados os ingredientes da despensa.',[{text:'Cancelar'},{text:'Sim, cozinhei',onPress:()=>{patch('pantry',a=>a.map(p=>({...p,qty:Math.max(0,Number(p.qty)-( ()=>{const used=scaledIngredients(r,data.servings).find(x=>norm(x.name)===norm(p.name));return used?(convertUnits(used.qty,used.unit,p.unit)??0):0} )())})));Alert.alert('Bom apetite!','Despensa atualizada com sucesso.')}}])};
  const toPantry=()=>{const purchased=data.shopping.filter(i=>i.done);if(!purchased.length)return Alert.alert('Seleciona os produtos comprados');Alert.alert('Atualizar despensa',`Adicionar ${purchased.length} produto(s) à despensa?`,[{text:'Cancelar'},{text:'Confirmar',onPress:()=>{
    patch('pantry',a=>{let next=[...a];purchased.forEach(item=>{const ix=next.findIndex(p=>norm(p.name)===norm(item.name));if(ix<0)next.push({...defaultProduct(item.name),name:item.name,qty:Number(item.qty),unit:item.unit});else{const converted=convertUnits(item.qty,item.unit,next[ix].unit);if(converted!==null)next[ix]={...next[ix],qty:Number(next[ix].qty)+converted};else next.push({...defaultProduct(item.name),name:`${item.name} (${item.unit})`,qty:Number(item.qty),unit:item.unit})};});return next;});patch('shopping',a=>a.filter(x=>!x.done));Alert.alert('Concluído','Produtos adicionados à despensa.');}}])};
  const planAuto=()=>{const cand=recommendations.filter(r=>r.missing===0);if(!cand.length)return Alert.alert('Despensa insuficiente','Adiciona produtos à despensa para gerar refeições com os ingredientes disponíveis.');patch('plan',old=>{let next={...old};DAYS.forEach((d,i)=>{next[`${d}:Almoço`]=cand[i%cand.length].id;next[`${d}:Jantar`]=cand[(i+2)%cand.length].id});return next});Alert.alert('Plano pronto','Plano semanal ajustado ao stock disponível e ao teu equipamento.')};
  const generateAI=async()=>{if(!API_URL){setAiResults([]);return Alert.alert('IA online indisponível','Ainda não existe um servidor de IA configurado. Entretanto podes usar as sugestões locais baseadas na tua despensa. Não são geradas por IA.')}setAiLoading(true);try{const r=await fetch(`${API_URL}/api/ai/recipes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pantry:data.pantry,equipment:data.equipment,servings:data.servings})});const v=await r.json();if(!r.ok)throw new Error(v.error||'Serviço indisponível');setAiResults(Array.isArray(v.recipes)?v.recipes:[]);if(!(v.recipes||[]).length)Alert.alert('Sem novas sugestões','Experimenta adicionar mais produtos.')}catch(e){Alert.alert('IA indisponível',String(e.message||e))}finally{setAiLoading(false)}};
  const pickReceipt=async()=>{try{const perm=await ImagePicker.requestCameraPermissionsAsync();if(!perm.granted)return Alert.alert('Permissão necessária','Autoriza a câmara para fotografar o talão.');const r=await ImagePicker.launchCameraAsync({quality:.65,allowsEditing:false});if(!r.canceled&&r.assets?.[0]?.uri){setReceiptPreview(r.assets[0].uri);patch('receipt',r.assets[0].uri);Alert.alert('Talão guardado','Fotografia guardada neste dispositivo. A leitura automática só estará disponível após ativar o serviço de OCR.')}}catch(e){Alert.alert('Câmara indisponível',String(e.message))}};
  const openExternal=async(url)=>{try{await Linking.openURL(url)}catch{Alert.alert('Não foi possível abrir o endereço')}};
  const payTwint=async(offer)=>{if(!paymentsReady||!API_URL)return Alert.alert('TWINT não está disponível','Ainda é preciso concluir o contrato comercial e a ligação ao prestador de pagamentos.');setPayBusy(true);try{const r=await fetch(`${API_URL}/api/checkout`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({offerId:offer.id,quantity:1})});const j=await r.json();if(!r.ok||!j.paymentUrl)throw Error(j.error||'Checkout não disponível');setModal('');await openExternal(j.paymentUrl)}catch(e){Alert.alert('Pagamento não iniciado',String(e.message||e))}finally{setPayBusy(false)}};
  const refreshMessage=feed.status==='online'?'Dados obtidos do servidor':'Sem ligação a uma fonte de preços verificada';
  const nav=[['Início','home-outline'],['Receitas','heart-outline'],['Despensa','basket-outline'],['Compras','cart-outline'],['Mais','ellipsis-horizontal']];
  const head=<View style={s.top}><Brand small/><TouchableOpacity onPress={()=>go('Perfil')}><Icon name="person-circle" size={27}/></TouchableOpacity></View>;
  const subhead=(title,icon='restaurant-outline')=><View style={s.top}><View style={{flexDirection:'row',alignItems:'center',gap:7}}><Image source={LOGO} style={{width:26,height:26}}/><Text style={{fontWeight:'900',fontSize:18,color:D}}>{title}</Text></View><TouchableOpacity onPress={()=>go('Início')}><Icon name="home-outline" size={20}/></TouchableOpacity></View>;
  const displayedRecipes=recipes.filter(r=>(filter==='Todas'||filter==='Favoritas'&&data.favorites.includes(r.id)||filter==='Da despensa'&&shortage(r,data.pantry,data.servings).length===0||filter==='Rápidas'&&r.minutes<=25||filter==='Marmitas'&&r.category==='Marmitas'||filter==='Air fryer'&&r.equipment.includes('airfryer')||r.category===filter)&&norm(r.name).includes(norm(search)));
  const recipeGrid=list=><View style={s.grid}>{list.map(r=><FoodCard key={r.id} r={r} onPress={()=>viewRecipe(r)} isFavorite={data.favorites.includes(r.id)} onFavorite={()=>favorite(r.id)}/>)}</View>;
  const priceCard=(item)=>{const values=(item.prices||[]).filter(p=>p&&Number.isFinite(Number(p.amount))&&p.verifiedAt&&p.sourceUrl);const cheapest=values.length?Math.min(...values.map(x=>Number(x.amount))):null;return <View key={item.id||item.name} style={s.panel}><Text style={s.productName}>{item.name}</Text><Text style={s.note}>{item.unit||'Unidade não indicada'} · {item.brand||'Marca não indicada'}</Text>{values.length?values.map(p=><TouchableOpacity key={p.store+p.productId} onPress={()=>openExternal(p.sourceUrl)} style={s.priceRow}><Text style={{fontWeight:'700',color:D}}>{p.store}</Text><View style={{alignItems:'flex-end'}}><Text style={{fontWeight:'900',color:Number(p.amount)===cheapest?G:D}}>{money(p.amount)} {Number(p.amount)===cheapest?'✓':''}</Text><Text style={s.smallMuted}>Verificado: {String(p.verifiedAt).slice(0,10)}</Text></View></TouchableOpacity>):<Text style={{fontSize:12,color:MUTED,marginTop:10}}>Preço indisponível · nenhuma fonte validada</Text>}</View>};
  const filteredExpenses=data.expenses.filter(e=>{const date=new Date(e.date+'T12:00:00'),current=new Date();if(!Number.isFinite(date.getTime()))return false;if(expensePeriod==='Ano')return date.getFullYear()===current.getFullYear();if(expensePeriod==='Semana'){const start=new Date(current);start.setDate(current.getDate()-6);start.setHours(0,0,0,0);return date>=start&&date<=current;}return date.getMonth()===current.getMonth()&&date.getFullYear()===current.getFullYear()});
  const savedShoppingCount=data.shopping.filter(p=>!p.done).length;
  const pantryStock=data.pantry.filter(p=>p.qty>0).length;
  const lowCount=data.pantry.filter(p=>p.qty<=p.min).length;
  const sponsored=promotions.items.filter(p=>p.status==='active');
  const priceList=feed.items.filter(p=>norm(p.name).includes(norm(priceQuery))&&(store==='Todos'||(p.prices||[]).some(q=>q.store===store)));
  const header=detail?subhead('Receita'):['Início','Mais'].includes(tab)?head:subhead(tab);
  if(!loaded)return <View style={{flex:1,backgroundColor:'#FFF',alignItems:'center',justifyContent:'center'}}><ActivityIndicator color={G}/></View>;
  if(!started)return <SafeAreaView style={{flex:1,backgroundColor:'#FFF'}} edges={['top','bottom']}><StatusBar barStyle="dark-content" backgroundColor="#FFFFFF"/><View style={{flex:1,backgroundColor:'#FFFFFF'}}>
    <View style={{alignItems:'center',paddingHorizontal:24,paddingTop:56,zIndex:2}}><Image source={LOGO} style={{width:113,height:105,resizeMode:'contain'}}/><Text style={{fontSize:35,color:G,fontWeight:'900',letterSpacing:-1.6}}>Meal<Text style={{color:O}}>Swiss</Text></Text><Text style={{color:D,textAlign:'center',marginTop:21,fontSize:14,lineHeight:21}}>Receitas, despensa e compras{'\n'}para uma vida mais prática{'\n'}e económica na Suíça.</Text></View>
    <Image source={require('./assets/alpes.jpg')} resizeMode="cover" style={{position:'absolute',bottom:0,width:'100%',height:'49%'}}/>
    <View style={{position:'absolute',left:20,right:20,bottom:14,paddingVertical:9,paddingHorizontal:10,borderRadius:18,backgroundColor:'rgba(255,255,255,0.90)'}}><CTA text="Começar" color={G} onPress={()=>{setStarted(true);AsyncStorage.setItem('mealswiss.welcome.v2','yes').catch(()=>{})}}/><TouchableOpacity onPress={()=>Alert.alert('Entrar','A autenticação de contas ficará disponível após a ativação do serviço seguro de utilizadores.')}><Text style={{color:MUTED,textAlign:'center',fontSize:12,marginTop:12,marginBottom:3}}>Já tens conta? <Text style={{color:G,fontWeight:'900'}}>Entrar</Text></Text></TouchableOpacity></View>
  </View></SafeAreaView>;
  return <SafeAreaView style={{flex:1,backgroundColor:'#FFF'}} edges={['top']}><StatusBar barStyle="dark-content" backgroundColor="#FFFFFF"/>{header}
  <ScrollView key={`${tab}-${detail?.id||''}`} style={{flex:1}} keyboardShouldPersistTaps="handled" contentContainerStyle={s.body}>
  {detail ? <>
    <Image source={recipeImage(detail)} style={s.detailHero}/>
    <View style={s.detailTitleRow}><Text style={[s.h1,{flex:1}]}>{detail.name}</Text><TouchableOpacity onPress={()=>favorite(detail.id)}><Icon size={24} name={data.favorites.includes(detail.id)?'heart':'heart-outline'} color={O}/></TouchableOpacity></View>
    <Text style={s.note}>◷ {detail.minutes} minutos    ♧ {data.servings} pessoas    ·    {detail.equipment.map(e=>EQUIPMENT.find(x=>x.key===e)?.label||e).join(' + ')||'Sem cozedura'}</Text>
    <Notice text="Os custos das receitas são calculados apenas com preços reais verificados. Nenhum preço é inventado."/>
    <H title="Ingredientes" subtitle={`Quantidades para ${data.servings} pessoas · stock da tua despensa`}/>
    <View style={s.panel}>{scaledIngredients(detail,data.servings).map((it,i)=>{const have=stockAmount(data.pantry,it),ok=have>=it.qty;return <View key={i} style={s.ingredientRow}><Icon name={ok?'checkmark-circle':'close-circle'} color={ok?G:RED} size={20}/><Text style={{flex:1,color:D,marginLeft:8,fontSize:13}}>{it.name}</Text><Text style={{color:ok?G:RED,fontWeight:'800',fontSize:12}}>{have} / {it.qty} {it.unit}</Text></View>})}</View>
    <CTA text="Adicionar ingredientes em falta" outline onPress={()=>{addShopping(shortage(detail,data.pantry,data.servings).map(x=>({...x,qty:Math.max(1,x.qty-stockAmount(data.pantry,x))})));go('Compras')}}/>
    <H title="Preparação"/>{detail.steps.map((step,i)=><View key={i} style={s.step}><View style={s.stepCircle}><Text style={{color:'#FFF',fontWeight:'900'}}>{i+1}</Text></View><Text style={{color:D,flex:1,lineHeight:20,fontSize:13}}>{step}</Text></View>)}
    <CTA text="✓ Confirmar que cozinhei" onPress={()=>confirmCook(detail)}/>
    <Text style={[s.note,{textAlign:'center'}]}>A despensa só é alterada após confirmação.</Text>
  </> : <>
    {tab==='Início'&&<>
      <Text style={{fontWeight:'900',color:D,fontSize:22,marginTop:2}}>Bom dia! 👋</Text><Text style={{fontWeight:'900',fontSize:18,color:'#1D3027',marginBottom:13}}>O que vamos cozinhar?</Text>
      <View style={s.searchBar}><Icon name="search-outline" color={MUTED}/><TextInput value={search} onChangeText={setSearch} style={{flex:1,color:D,fontSize:13,padding:0}} placeholder="Pesquisar receitas, ingredientes..." placeholderTextColor={MUTED} onFocus={()=>setTab('Receitas')}/></View>
      <View style={s.shortcuts}>{[['Receitas','restaurant-outline','Receitas'],['Despensa','medkit-outline','Despensa'],['Lista de compras','cart-outline','Compras'],['Plano semanal','calendar-outline','Plano']].map(([t,i,target],n)=><TouchableOpacity key={t} onPress={()=>go(target)} style={[s.shortcut,{backgroundColor:n===0||n===3?'#FFF5EA':'#ECF8F0'}]}><View style={[s.shortIcon,{backgroundColor:n===0||n===3?'#FFF0E0':'#E5F5EC'}]}><Icon name={i} size={24} color={n%2?G:O}/></View><Text style={s.shortLabel}>{t}</Text></TouchableOpacity>)}</View>
      <View style={s.sectionInline}><Text style={s.h3}>Inspiração para a tua cozinha</Text><Text style={s.adLabel}>Publicidade</Text></View>
      <TouchableOpacity style={s.adCard} onPress={()=>go('Marmitas')}><Image source={require('./assets/airfryer.jpg')} style={s.adImage}/><View style={{padding:11}}><Text style={{color:D,fontSize:14,fontWeight:'900'}}>Cozinha mais saudável em casa</Text><Text style={s.note}>Descobre ideias para a air fryer e outros equipamentos.</Text></View></TouchableOpacity>
      <TouchableOpacity style={s.cookCallout} onPress={()=>go('Cozinha para Ti')}><Text style={{fontSize:28}}>👩‍🍳</Text><View style={{flex:1}}><Text style={{color:G,fontSize:14,fontWeight:'900'}}>Queres que cozinhe para ti?</Text><Text style={s.note}>Refeições caseiras perto de ti</Text></View><Icon name="arrow-forward" color={O} size={22}/></TouchableOpacity>
      <H title="As tuas sugestões" subtitle="Adaptadas aos ingredientes e ao teu equipamento" action="Ver todas" onPress={()=>go('Receitas')}/>
      <View style={s.homeRecipes}>{recommendations.slice(0,3).map(r=><HomeRecipeCard key={r.id} r={r} onPress={()=>viewRecipe(r)} isFavorite={data.favorites.includes(r.id)} onFavorite={()=>favorite(r.id)}/>)}</View>
      <H title="Preços do dia" subtitle="Coop · Migros · Denner · Lidl · Aldi" action="Comparar" onPress={()=>go('Comparador')}/>
      <Notice kind="warn" text={feed.status==='online'?'Preços reais do servidor, com fontes e datas individuais.':'Ainda não existem preços oficiais verificados. A aplicação não apresenta preços fictícios.'}/>
      {feed.items.slice(0,3).map(priceCard)}
      {sponsored.length>0&&<><H title="Em destaque" subtitle="Conteúdos pagos por marcas"/>{sponsored.map(p=><TouchableOpacity key={p.id} style={s.panel} onPress={()=>p.url&&openExternal(p.url)}><Text style={s.adLabel}>Patrocinado</Text><Text style={s.productName}>{p.title}</Text><Text style={s.note}>{p.description||''}</Text></TouchableOpacity>)}</>}
    </>}
    {tab==='Receitas'&&<><H title="Receitas para ti" subtitle={`${recipes.length} receitas adequadas ao teu equipamento`}/><View style={s.searchBar}><Icon name="search-outline" color={MUTED}/><TextInput placeholder="Pesquisar receitas..." placeholderTextColor={MUTED} value={search} onChangeText={setSearch} style={{flex:1,fontSize:13,color:D,padding:0}}/></View><ScrollView horizontal showsHorizontalScrollIndicator={false} style={{marginVertical:12}}>{['Todas','Da despensa','Rápidas','Económicas','Air fryer','Marmitas','Forno','Favoritas','Saudáveis'].map(f=><Pill key={f} text={f} active={filter===f} onPress={()=>setFilter(f)}/>)}</ScrollView><View style={s.inline}><Text style={s.note}>{displayedRecipes.length} resultados</Text><TouchableOpacity onPress={()=>go('Equipamentos')}><Text style={s.link}>⚙ Equipamentos</Text></TouchableOpacity></View>{displayedRecipes.length?recipeGrid(displayedRecipes):<Notice text="Não encontrámos receitas para este filtro. Ativa mais equipamentos no perfil."/>}<CTA text={aiLoading?'A gerar sugestões...':'✨ Pedir novas receitas à IA'} disabled={aiLoading} onPress={generateAI}/>{aiResults.map((r,i)=><View key={i} style={s.panel}><Text style={s.productName}>{r.name}</Text><Text style={s.note}>{r.description||''}</Text><Text style={s.note}>Sugestão de IA — confirma quantidades e segurança alimentar.</Text></View>)}</>}
    {tab==='Despensa'&&<><H title="A minha despensa" subtitle={`${pantryStock} produtos em stock · ${lowCount} a repor`}/><ScrollView horizontal showsHorizontalScrollIndicator={false} style={{marginBottom:12}}>{['Todos','Em stock','Stock baixo','Esgotado'].map(f=><Pill key={f} text={f} active={pantryFilter===f} onPress={()=>setPantryFilter(f)}/>)}</ScrollView><View style={{marginBottom:7}}>{data.pantry.length?data.pantry.filter(p=>pantryFilter==='Todos'||pantryFilter==='Em stock'&&p.qty>p.min||pantryFilter==='Stock baixo'&&p.qty>0&&p.qty<=p.min||pantryFilter==='Esgotado'&&p.qty===0).map(p=><ProductRow key={p.name} p={p} qty={p.qty} unit={p.unit} onMinus={()=>adjustPantry(p.name,-1)} onPlus={()=>adjustPantry(p.name,1)}/>):<View><Text style={s.emptyTitle}>A tua despensa começa aqui</Text><Text style={s.note}>Regista os produtos reais que tens em casa para receberes sugestões personalizadas.</Text></View>}</View><CTA text="+ Adicionar produto" onPress={()=>prepareModal('pantry')}/><H title="Adicionar rapidamente" subtitle="Escolhe um produto e indica a quantidade"/><View style={s.quickGrid}>{DEFAULT_PRODUCTS.slice(0,12).map(p=><TouchableOpacity key={p.name} onPress={()=>prepareModal('pantry',p.name,'1',p.unit)} style={s.quickTile}><Text style={{fontSize:23}}>{p.emoji}</Text><Text style={{fontSize:10,color:D,fontWeight:'800',textAlign:'center',marginTop:5}}>{p.name}</Text></TouchableOpacity>)}</View></>}
    {tab==='Compras'&&<><H title="Lista de compras" subtitle={`${savedShoppingCount} produtos por comprar`}/><View style={s.panel}>{data.shopping.length?data.shopping.map(p=><View key={p.id} style={s.shopRow}><TouchableOpacity onPress={()=>patch('shopping',a=>a.map(x=>x.id===p.id?{...x,done:!x.done}:x))}><Icon name={p.done?'checkbox':'square-outline'} color={G} size={22}/></TouchableOpacity><View style={{flex:1,marginLeft:12}}><Text style={{fontSize:14,color:D,fontWeight:'700',textDecorationLine:p.done?'line-through':'none'}}>{p.name}</Text><Text style={s.note}>{p.qty} {p.unit}</Text></View><TouchableOpacity onPress={()=>patch('shopping',a=>a.filter(x=>x.id!==p.id))}><Icon name="trash-outline" color={MUTED}/></TouchableOpacity></View>):<Text style={s.note}>A lista está vazia. Adiciona produtos ou ingredientes de uma receita.</Text>}</View><CTA text="+ Adicionar à lista" onPress={()=>prepareModal('shopping')}/><CTA text="✓ Confirmar compras e repor stock" outline onPress={toPantry}/><View style={{marginTop:10}}><H title="Comparar preços reais" subtitle="Fontes oficiais, quando disponíveis" action="Abrir" onPress={()=>go('Comparador')}/><Notice kind="warn" text="Não fazemos estimativas de preços sem uma fonte válida. Os preços da lista serão calculados quando houver cobertura de produtos verificados."/></View></>}
    {tab==='Plano'&&<><H title="Plano semanal" subtitle="Pequeno-almoço · almoço · jantar"/><ScrollView horizontal showsHorizontalScrollIndicator={false}>{DAYS.map(d=><Pill text={d} key={d} active={selectedDay===d} onPress={()=>setSelectedDay(d)}/>)}</ScrollView><Text style={[s.h3,{marginTop:17,marginBottom:12}]}>{selectedDay} · refeições</Text>{MEALS.map(meal=>{const id=data.plan[`${selectedDay}:${meal}`],r=catalogue.find(x=>x.id===id);return <TouchableOpacity key={meal} style={s.planRow} onPress={()=>{setSelectedMeal(meal);setModal('plan')}}><View style={{flex:1}}><Text style={s.note}>{meal}</Text><Text style={s.productName}>{r?r.name:'Escolher uma receita +'}</Text></View>{r?<Image source={recipeImage(r)} style={{width:64,height:53,borderRadius:9}}/>:<Icon name="add-circle-outline" size={25}/>}</TouchableOpacity>})}<CTA text="✨ Gerar plano com a minha despensa" onPress={planAuto}/><Notice text="O plano automático local escolhe apenas receitas possíveis com o stock e os equipamentos que assinalaste."/></>}
    {tab==='Marmitas'&&<><Image source={photos[1]} style={{width:'100%',height:180,borderRadius:16}}/><H title="Prepara hoje e simplifica a semana!" subtitle="Receitas adequadas a refeições para guardar"/>{recipeGrid(recipes.filter(r=>r.category==='Marmitas'))}<CTA text="Adicionar ingredientes de marmitas" onPress={()=>{addShopping(recipes.filter(r=>r.category==='Marmitas').slice(0,2).flatMap(r=>r.ingredients));go('Compras')}}/></>}
    {tab==='Comparador'&&<><H title="Comparar preços" subtitle="Preços verificados nos supermercados suíços"/><View style={s.searchBar}><Icon name="search-outline" color={MUTED}/><TextInput placeholder="Arroz, óleo, massa, leite..." value={priceQuery} onChangeText={setPriceQuery} style={{flex:1,padding:0,color:D,fontSize:13}}/></View><ScrollView horizontal showsHorizontalScrollIndicator={false} style={{marginVertical:12}}>{['Todos',...STORES.map(v=>v.key)].map(x=><Pill key={x} text={x} active={store===x} onPress={()=>setStore(x)}/>)}</ScrollView><Notice kind="warn" text={feed.status==='online'?'Preços originados no servidor. Consulta a data e a fonte de cada produto.':`Sem preços validados atualmente. ${refreshMessage}. Não apresentamos preços aleatórios.`}/>{priceList.map(priceCard)}{!priceList.length&&<View style={s.panel}><Text style={s.emptyTitle}>Ainda sem preços oficiais confirmados</Text><Text style={s.note}>Arroz, massa, óleo e outros produtos vão aparecer aqui depois de as fontes estarem integradas e autorizadas.</Text></View>}<H title="Sites dos supermercados" subtitle="Podes consultar os sites oficiais"/>{STORES.map(x=><TouchableOpacity key={x.key} onPress={()=>openExternal(x.url)} style={s.storeLine}><View style={[s.storeDot,{backgroundColor:x.color}]}/><Text style={[s.productName,{flex:1}]}>{x.key}</Text><Icon name="open-outline" color={MUTED}/></TouchableOpacity>)}</>}
    {tab==='Histórico'&&<><H title="Histórico de preços" subtitle="Evolução baseada em recolhas verificadas"/><Notice kind="warn" text="O histórico será desenhado a partir de observações reais com data. Ainda não existem séries de preços verificadas para mostrar."/>{feed.items.filter(x=>x.history?.length).map(p=>{const obs=p.history.slice(0,12).reverse();const max=Math.max(1,...obs.map(x=>Number(x.amount)||0));return <View key={p.id} style={s.panel}><Text style={s.productName}>{p.name}</Text><View style={{height:110,flexDirection:'row',alignItems:'flex-end',gap:5,marginVertical:12}}>{obs.map((x,i)=><View key={i} style={{backgroundColor:i===obs.length-1?O:'#B5DCC6',flex:1,height:`${Math.max(5,Math.round(Number(x.amount)/max*100))}%`,borderRadius:4}}/>)}</View>{obs.map((h,i)=><Text key={i} style={s.note}>{h.date} · {h.store} · {money(h.amount)}</Text>)}</View>})}</>}
    {tab==='Despesas'&&<><H title="As minhas despesas" subtitle="Regista o que realmente gastaste"/><View style={{flexDirection:'row',justifyContent:'center',marginBottom:12}}>{['Semana','Mês','Ano'].map(x=><Pill key={x} text={x} active={expensePeriod===x} onPress={()=>setExpensePeriod(x)}/>)}</View><View style={s.expenseTotal}><Text style={s.note}>Total real do período</Text><Text style={{fontSize:28,fontWeight:'900',color:G}}>{money(filteredExpenses.reduce((t,x)=>t+Number(x.amount||0),0))}</Text><Text style={s.note}>{filteredExpenses.length} despesas registadas</Text></View><CTA text="+ Registar despesa" onPress={()=>{setInputName('Compras');setInputQty('');setModal('expense')}}/>{filteredExpenses.slice().reverse().map(x=><View key={x.id} style={s.shopRow}><Icon name="receipt-outline"/><View style={{flex:1,marginLeft:10}}><Text style={s.productName}>{x.name}</Text><Text style={s.note}>{x.date}</Text></View><Text style={{color:G,fontWeight:'900'}}>{money(x.amount)}</Text></View>)}{!filteredExpenses.length&&<Notice text="Ainda não registaste despesas neste período. Não são apresentados valores fictícios."/>}</>}
    {tab==='Talão'&&<><H title="Ler talão" subtitle="Guarda o comprovativo das tuas compras"/>{receiptPreview?<Image source={{uri:receiptPreview}} style={{height:330,width:'100%',borderRadius:14,resizeMode:'contain',backgroundColor:PALE}}/>:<View style={[s.panel,{alignItems:'center',padding:30}]}><Icon name="receipt-outline" size={52} color={G}/><Text style={[s.note,{textAlign:'center',marginTop:10}]}>Ainda não foi fotografado nenhum talão.</Text></View>}<CTA text="📷 Fotografar talão" onPress={pickReceipt}/><Notice kind="warn" text="A fotografia fica guardada localmente. O reconhecimento OCR de produtos e preços ainda requer um serviço configurado; podes adicionar produtos manualmente à despensa."/><CTA text="Adicionar produtos manualmente" outline onPress={()=>go('Despensa')}/></>}
    {tab==='Cozinha para Ti'&&<><H title="Queres que cozinhe para ti?" subtitle="Descobre cozinheiros e refeições perto de ti"/><Notice kind="warn" text={paymentsReady?'TWINT configurado. Os pagamentos são sempre confirmados pelo servidor, nunca pelo regresso do navegador.':'Marketplace em preparação. Os pagamentos reais só serão permitidos com cozinheiros verificados e conta comercial TWINT ativa.'}/>{cooks.items.length?cooks.items.map(c=><View key={c.id} style={s.panel}><Text style={s.productName}>{c.displayName}</Text><Text style={s.note}>{c.location} · {c.description}</Text><CTA text="Ver refeições" outline onPress={()=>setModal(`cook:${c.id}`)}/></View>):<View style={[s.panel,{alignItems:'center',padding:25}]}><Text style={{fontSize:42}}>👩‍🍳</Text><Text style={[s.h3,{textAlign:'center'}]}>Em breve: refeições caseiras locais</Text><Text style={[s.note,{textAlign:'center'}]}>Os perfis e encomendas só aparecem após validação dos cozinheiros, condições legais e pagamentos.</Text></View>}<H title="Pagar com TWINT"/><Notice text="O pagamento é processado fora do MealSwiss por um prestador autorizado. A encomenda só fica paga depois da confirmação segura do prestador."/></>}
    {tab==='Equipamentos'&&<><H title="A minha cozinha" subtitle="Que equipamentos tens disponíveis?"/><Text style={s.note}>O catálogo, as sugestões e o planeamento respeitam estas escolhas.</Text>{EQUIPMENT.map(e=><TouchableOpacity key={e.key} style={s.equipmentRow} onPress={()=>patch('equipment',old=>old.includes(e.key)?old.filter(x=>x!==e.key):[...old,e.key])}><Icon name={e.icon} size={23}/><Text style={[s.productName,{flex:1,marginLeft:13}]}>{e.label}</Text><Icon name={data.equipment.includes(e.key)?'checkbox':'square-outline'} color={G} size={25}/></TouchableOpacity>)}<H title="Pessoas por refeição"/><View style={s.inline}><TouchableOpacity onPress={()=>patch('servings',n=>Math.max(1,n-1))} style={s.counter}><Icon name="remove"/></TouchableOpacity><Text style={{fontWeight:'900',fontSize:18,color:D}}>{data.servings}</Text><TouchableOpacity onPress={()=>patch('servings',n=>Math.min(12,n+1))} style={s.counter}><Icon name="add"/></TouchableOpacity></View><CTA text="Guardar e ver receitas" onPress={()=>go('Receitas')}/></>}
    {tab==='Amigos'&&<><View style={[s.panel,{alignItems:'center',padding:30}]}><Image source={LOGO} style={{height:86,width:86}}/><Text style={s.h1}>MealSwiss Amigos</Text><Text style={[s.note,{textAlign:'center'}]}>Partilha a aplicação com amigos e família.</Text></View><CTA text="Partilhar MealSwiss" onPress={()=>Share.share({message:'Descobre o MealSwiss — Planeia. Cozinha. Poupa. 🇨🇭'})}/><Notice text="O programa de recompensas não está ativo. Não anunciamos pontos fictícios."/></>}
    {tab==='Perfil'&&<><H title="O meu perfil" subtitle="Preferências e controlo da aplicação"/><View style={s.panel}>{[['A minha cozinha','Equipamentos','hardware-chip-outline'],['Plano semanal','Plano','calendar-outline'],['Comparador de preços','Comparador','pricetag-outline'],['Despesas','Despesas','stats-chart-outline'],['Ler talão','Talão','receipt-outline'],['MealSwiss Amigos','Amigos','people-outline'],['Administração','Admin','settings-outline']].map(([label,target,icon])=><TouchableOpacity key={target} style={s.moreRow} onPress={()=>go(target)}><Icon name={icon}/><Text style={{flex:1,color:D,fontWeight:'700',marginLeft:13}}>{label}</Text><Icon name="chevron-forward" size={16} color={MUTED}/></TouchableOpacity>)}</View><CTA text="Ver ecrã de boas-vindas" outline onPress={()=>{setStarted(false);AsyncStorage.removeItem('mealswiss.welcome.v2').catch(()=>{})}}/><CTA text="Repor dados locais" outline color={RED} onPress={()=>Alert.alert('Apagar os teus dados?','Apaga a despensa, compras, plano e despesas deste dispositivo.',[{text:'Cancelar'},{text:'Apagar',style:'destructive',onPress:()=>setData(initial)}])}/></>}
    {tab==='Admin'&&<><H title="Back-office MealSwiss" subtitle="Gestão de receitas, utilizadores, marcas e campanhas"/><Notice kind="warn" text="O back-office é um painel web protegido no servidor. Não é adequado guardar credenciais de administrador dentro do APK."/>{['Receitas e categorias','Utilizadores e cozinheiros','Produtos e preços verificados','Campanhas e produtos patrocinados','Publicidade Google: identificadores e estado','Encomendas, comissões e TWINT'].map(t=><View style={s.moreRow} key={t}><Icon name="checkmark-circle-outline"/><Text style={{marginLeft:13,flex:1,color:D}}>{t}</Text></View>)}<CTA text="Abrir back-office" disabled={!API_URL} onPress={()=>openExternal(`${API_URL}/admin`)}/>{!API_URL&&<Notice text="Define EXPO_PUBLIC_API_URL e instala o servidor incluído neste projeto antes de usar o back-office."/>}</>}
    {tab==='Mais'&&<><H title="Descobrir MealSwiss"/>{[['Plano semanal','Plano','calendar-outline'],['Marmitas','Marmitas','fast-food-outline'],['Comparar supermercados','Comparador','pricetag-outline'],['Histórico de preços','Histórico','trending-up-outline'],['Despesas','Despesas','stats-chart-outline'],['Ler talão','Talão','receipt-outline'],['Cozinha para Ti','Cozinha para Ti','people-outline'],['A minha cozinha','Equipamentos','options-outline'],['MealSwiss Amigos','Amigos','gift-outline'],['Perfil','Perfil','person-outline'],['Back-office','Admin','settings-outline']].map(([label,target,icon])=><TouchableOpacity key={target} style={s.moreRow} onPress={()=>go(target)}><Icon name={icon} size={22}/><Text style={{marginLeft:13,flex:1,color:D,fontWeight:'800'}}>{label}</Text><Icon name="chevron-forward" color={MUTED} size={17}/></TouchableOpacity>)}</>}
  </>}
  </ScrollView>
  <View style={[s.nav,{paddingBottom:Math.max(insets.bottom,12)}]}>{nav.map(([t,i])=><TouchableOpacity key={t} style={s.navItem} onPress={()=>go(t)} accessibilityRole="tab" accessibilityLabel={t} accessibilityState={{selected:tab===t}}><Icon name={tab===t?i.replace('-outline',''):i} color={tab===t?G:'#96A39A'} size={21}/><Text style={{fontSize:9,fontWeight:tab===t?'900':'600',color:tab===t?G:MUTED,marginTop:5}}>{t}</Text></TouchableOpacity>)}</View>
  <Modal visible={!!modal} animationType="slide" transparent onRequestClose={()=>setModal('')}><View style={s.overlay}><View style={[s.modal,{paddingBottom:Math.max(insets.bottom,20)}]}><View style={s.modalTitle}><Text style={s.h3}>{modal==='pantry'?'Adicionar à despensa':modal==='shopping'?'Adicionar à lista':modal==='plan'?`${selectedDay} · ${selectedMeal}`:modal==='expense'?'Registar despesa': 'Detalhes'}</Text><TouchableOpacity onPress={()=>setModal('')}><Icon name="close" size={23} color={D}/></TouchableOpacity></View>
    {modal==='plan'?<ScrollView style={{maxHeight:400}}>{recipes.map(r=><TouchableOpacity key={r.id} style={s.planChoice} onPress={()=>{patch('plan',p=>({...p,[`${selectedDay}:${selectedMeal}`]:r.id}));setModal('')}}><Image source={recipeImage(r)} style={{height:50,width:55,borderRadius:8}}/><Text style={{flex:1,fontSize:13,fontWeight:'800',marginLeft:10,color:D}}>{r.name}</Text><Icon name="add-circle-outline"/></TouchableOpacity>)}</ScrollView>:modal.startsWith('cook:')?<><Notice kind={paymentsReady?'neutral':'warn'} text={paymentsReady?'Seleciona a refeição. O pagamento é processado no checkout seguro do prestador.':'Os pagamentos TWINT continuam indisponíveis enquanto a integração comercial não estiver ativa.'}/><ScrollView style={{maxHeight:320}}>{offers.items.filter(o=>o.cookId===modal.slice(5)).map(o=><View key={o.id} style={s.panel}><Text style={s.productName}>{o.name}</Text><Text style={s.note}>{o.description||''}</Text><View style={s.inline}><Text style={{fontWeight:'900',color:G}}>{money(o.priceCHF)}</Text><CTA text={payBusy?'A abrir TWINT...':'Pagar com TWINT'} disabled={!paymentsReady||payBusy} onPress={()=>payTwint(o)}/></View></View>)}{!offers.items.some(o=>o.cookId===modal.slice(5))&&<Text style={s.note}>Este cozinheiro ainda não disponibilizou refeições.</Text>}</ScrollView><CTA text="Voltar" outline onPress={()=>setModal('')}/></>:<>
    <Text style={s.formLabel}>{modal==='expense'?'Descrição':'Nome do produto'}</Text><TextInput style={s.formInput} value={inputName} onChangeText={setInputName} placeholder="Escreve aqui"/>
    <Text style={s.formLabel}>{modal==='expense'?'Montante real em CHF':'Quantidade'}</Text><TextInput style={s.formInput} value={inputQty} keyboardType="decimal-pad" onChangeText={setInputQty} placeholder="0"/>
    {modal!=='expense'&&<><Text style={s.formLabel}>Unidade</Text><View style={{flexDirection:'row',flexWrap:'wrap',marginVertical:8}}>{['un','g','kg','ml','L'].map(x=><Pill key={x} text={x} active={inputUnit===x} onPress={()=>setInputUnit(x)}/>)}</View></>}
    <CTA text="Guardar" onPress={()=>{if(modal==='pantry')savePantry();if(modal==='shopping')saveShopping();if(modal==='expense'){let v=Number(String(inputQty).replace(',','.'));if(!(v>0)||!inputName.trim())return Alert.alert('Verifica o nome e o montante');patch('expenses',a=>[...a,{id:String(Date.now()),name:inputName.trim(),amount:v,date:new Date().toISOString().slice(0,10)}]);setModal('')}}}/></>}
  </View></View></Modal>
  </SafeAreaView>
}
export default function App(){return <SafeAreaProvider><MealSwiss/></SafeAreaProvider>}
